                                                                                                                                                                                                                
  CREATE TABLE "FMP_ROLE_PERMISSION"                                                                                                                                                                  
   (	"ROLE_PERMISSION_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"ROLE_ID" NUMBER(20,0),                                                                                                                                                                                        
	"PERMISSION_ID" NUMBER(20,0),                                                                                                                                                                                  
	"IS_ENABLE" NUMBER DEFAULT 1,                                                                                                                                                                                  
	"REMARK" NVARCHAR2(256),                                                                                                                                                                                       
	"TENANT_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                      
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                     
	"CREATION_DATE" DATE DEFAULT sysdate,                                                                                                                                                                          
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                     
	"UPDATED_DATE" DATE DEFAULT sysdate,                                                                                                                                                                           
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0,                                                                                                                                                                              
	 PRIMARY KEY ("ROLE_PERMISSION_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                           
   ) ;                                                                                                                                                                                                          


